/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import gsorthpBy = require( './index' );


// FUNCTIONS //

/**
* Callback function.
*
* @param a - first value
* @param b - second value
* @returns comparison result
*/
function fcn( a: number, b: number ): number {
	if ( a < b ) {
		return -1;
	}
	if ( a > b ) {
		return 1;
	}
	return 0;
}


// TESTS //

// The function returns a numeric array...
{
	const x = new Float64Array( 10 );

	gsorthpBy( x.length, x, 1, fcn ); // $ExpectType Float64Array
	gsorthpBy( x.length, new AccessorArray( x ), 1, fcn ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	gsorthpBy( '10', x, 1, fcn ); // $ExpectError
	gsorthpBy( true, x, 1, fcn ); // $ExpectError
	gsorthpBy( false, x, 1, fcn ); // $ExpectError
	gsorthpBy( null, x, 1, fcn ); // $ExpectError
	gsorthpBy( undefined, x, 1, fcn ); // $ExpectError
	gsorthpBy( [], x, 1, fcn ); // $ExpectError
	gsorthpBy( {}, x, 1, fcn ); // $ExpectError
	gsorthpBy( ( x: number ): number => x, x, 1, fcn ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a numeric array...
{
	gsorthpBy( 10, 10, 1, fcn ); // $ExpectError
	gsorthpBy( 10, '10', 1, fcn ); // $ExpectError
	gsorthpBy( 10, true, 1, fcn ); // $ExpectError
	gsorthpBy( 10, false, 1, fcn ); // $ExpectError
	gsorthpBy( 10, null, 1, fcn ); // $ExpectError
	gsorthpBy( 10, undefined, 1, fcn ); // $ExpectError
	gsorthpBy( 10, [ '1' ], 1, fcn ); // $ExpectError
	gsorthpBy( 10, {}, 1, fcn ); // $ExpectError
	gsorthpBy( 10, ( x: number ): number => x, 1, fcn ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Float64Array( 10 );

	gsorthpBy( x.length, x, '10', fcn ); // $ExpectError
	gsorthpBy( x.length, x, true, fcn ); // $ExpectError
	gsorthpBy( x.length, x, false, fcn ); // $ExpectError
	gsorthpBy( x.length, x, null, fcn ); // $ExpectError
	gsorthpBy( x.length, x, undefined, fcn ); // $ExpectError
	gsorthpBy( x.length, x, [], fcn ); // $ExpectError
	gsorthpBy( x.length, x, {}, fcn ); // $ExpectError
	gsorthpBy( x.length, x, ( x: number ): number => x, fcn ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a function...
{
	const x = new Float64Array( 10 );

	gsorthpBy( x.length, x, 1, 10 ); // $ExpectError
	gsorthpBy( x.length, x, 1, '10' ); // $ExpectError
	gsorthpBy( x.length, x, 1, true ); // $ExpectError
	gsorthpBy( x.length, x, 1, false ); // $ExpectError
	gsorthpBy( x.length, x, 1, null ); // $ExpectError
	gsorthpBy( x.length, x, 1, undefined ); // $ExpectError
	gsorthpBy( x.length, x, 1, [] ); // $ExpectError
	gsorthpBy( x.length, x, 1, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );

	gsorthpBy(); // $ExpectError
	gsorthpBy( x.length ); // $ExpectError
	gsorthpBy( x.length, x ); // $ExpectError
	gsorthpBy( x.length, x, 1 ); // $ExpectError
	gsorthpBy( x.length, x, 1, fcn, {}, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a numeric array...
{
	const x = new Float64Array( 10 );

	gsorthpBy.ndarray( x.length, x, 1, 0, fcn ); // $ExpectType Float64Array
	gsorthpBy.ndarray( x.length, new AccessorArray( x ), 1, 0, fcn ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Float64Array( 10 );

	gsorthpBy.ndarray( '10', x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( true, x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( false, x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( null, x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( undefined, x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( [], x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( {}, x, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( ( x: number ): number => x, x, 1, 0, fcn ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a numeric array...
{
	gsorthpBy.ndarray( 10, 10, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, '10', 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, true, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, false, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, null, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, undefined, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, [ '1' ], 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, {}, 1, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( 10, ( x: number ): number => x, 1, 0, fcn ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const x = new Float64Array( 10 );

	gsorthpBy.ndarray( x.length, x, '10', 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, true, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, false, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, null, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, undefined, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, [], 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, {}, 0, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, ( x: number ): number => x, 0, fcn ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const x = new Float64Array( 10 );

	gsorthpBy.ndarray( x.length, x, 1, '10', fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, true, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, false, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, null, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, undefined, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, [], fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, {}, fcn ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, ( x: number ): number => x, fcn ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a function...
{
	const x = new Float64Array( 10 );

	gsorthpBy.ndarray( x.length, x, 1, 0, 10 ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, '10' ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, true ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, false ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, null ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, undefined ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, [] ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, {} ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );

	gsorthpBy.ndarray(); // $ExpectError
	gsorthpBy.ndarray( x.length ); // $ExpectError
	gsorthpBy.ndarray( x.length, x ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1 ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0 ); // $ExpectError
	gsorthpBy.ndarray( x.length, x, 1, 0, fcn, {}, {} ); // $ExpectError
}
